test.before(async()=>{const template=decodeURIComponent(source.pathname.slice(1));if(!/^[a-z][a-z0-9_]{0,62}$/.test(template))throw new Error("Invalid template");name=`condola_b011_${randomUUID().replaceAll("-","")}`;admin=new Client({connectionString:withDatabase(source,"postgres")});await admin.connect();await admin.query(`CREATE DATABASE "${name}" TEMPLATE "${template}"`);owned=true;db=new Client({connectionString:withDatabase(source,name)});await db.connect();for(const [table,file] of [["handover_records","20261031100214_b011_handover_records.sql"],["settlement_sources","20261031100216_b011_settlement.sql"]])if(!(await db.query(`SELECT to_regclass($1) IS NOT NULL AS installed`,[`app.${table}`])).rows[0].installed)await db.query(await readFile(new URL(`../../supabase/migrations/${file}`,import.meta.url),"utf8"));await db.query(`CREATE FUNCTION app.b011_test_pin_candidate(p_actor uuid,p_session uuid,p_org uuid,p_lease uuid,p_evidence uuid,p_attribution uuid,p_live uuid,p_env text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 IF current_setting('request.jwt.claim.sub',true) IS DISTINCT FROM p_actor::text OR NOT EXISTS(SELECT 1 FROM public.auth_sessions s WHERE s.id=p_session AND s.user_id=p_actor AND s.revoked_at IS NULL AND s.expires_at>clock_timestamp()) OR NOT EXISTS(SELECT 1 FROM public.organizations o JOIN public.org_members m ON m.org_id=coalesce(o.live_org_id,o.id) AND m.user_id=p_actor AND m.status='active' AND m.role IN ('admin','accountant') JOIN public.leases l ON l.org_id=o.id AND l.id=p_lease JOIN public.platform_settings f ON f.key='deposit_settlements' WHERE o.id=p_org AND coalesce(o.live_org_id,o.id)=p_live AND o.environment::text=p_env AND o.feature_flags->'deposit_settlements'='true'::jsonb AND f.value->'enabled'='true'::jsonb AND jsonb_typeof(f.value->'allowed_org_ids')='array' AND f.value->'allowed_org_ids' @> jsonb_build_array(o.id::text)) THEN RAISE EXCEPTION 'not authorized' USING ERRCODE='42501'; END IF;
 PERFORM id FROM app.settlement_evidence WHERE org_id=p_org AND lease_id=p_lease AND id=p_evidence FOR SHARE NOWAIT; IF NOT FOUND THEN RAISE EXCEPTION 'not found' USING ERRCODE='42501'; END IF;
 PERFORM id FROM app.settlement_attributions WHERE org_id=p_org AND lease_id=p_lease AND id=p_attribution AND evidence_id=p_evidence FOR SHARE NOWAIT; IF NOT FOUND THEN RAISE EXCEPTION 'not found' USING ERRCODE='42501'; END IF;
END $$; REVOKE ALL ON FUNCTION app.b011_test_pin_candidate(uuid,uuid,uuid,uuid,uuid,uuid,uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION app.b011_test_pin_candidate(uuid,uuid,uuid,uuid,uuid,uuid,uuid,text) TO service_role`);process.env.DATABASE_URL=withDatabase(source,name);await resetAndSeed();});
