    await db.query(`INSERT INTO ledger_entries(org_id,transaction_id,account,amount_minor,currency,contact_id,property_id,lease_id,invoice_id) VALUES($1,$2,'tenant_receivable',200000,'TWD',$3,$4,$5,$6),($1,$2,'rental_income',-100000,'TWD',$3,$4,$5,$6),($1,$2,$7::ledger_account,-100000,'TWD',$3,$4,$5,$6)`,[ORG_ID,ledger,contact,property,lease,invoice,wrongLedger?"rental_income":"deposits_held"]);
