async function financial(lease:string) {return (await db.query(`SELECT (SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.id),'[]'::jsonb) FROM payments p WHERE p.lease_id=$1) payments,(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.id),'[]'::jsonb) FROM invoices i WHERE i.lease_id=$1) invoices,(SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb) FROM invoice_lines l JOIN invoices i ON i.id=l.invoice_id WHERE i.lease_id=$1) invoice_lines,(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.id),'[]'::jsonb) FROM payment_allocations a JOIN payments p ON p.id=a.payment_id WHERE p.lease_id=$1) allocations,(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.id),'[]'::jsonb) FROM ledger_transactions t WHERE t.lease_id=$1) ledgers,(SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.id),'[]'::jsonb) FROM ledger_entries e WHERE e.lease_id=$1) entries`,[lease])).rows[0];}
