  const invoice=(await db.query<{id:string}>(`INSERT INTO invoices(org_id,property_id,lease_id,bill_to_contact_id,invoice_number,currency,due_date,status) VALUES($1,$2,$3,$4,$5,'TWD',current_date,'draft') RETURNING id`,[ORG_ID,source.property_id,f.lease,source.contact_id,`B011-FACADE-${randomUUID()}`])).rows[0].id;
  await db.query(`INSERT INTO invoice_lines(org_id,invoice_id,line_no,charge_type,description,quantity,unit_amount_minor,amount_minor) VALUES($1,$2,1,'rent','Synthetic open line',1,10000,10000)`,[ORG_ID,invoice]);await db.query(`UPDATE invoices SET status='open' WHERE id=$1`,[invoice]);return invoice;
