async function waitForBlocker(pid:number) {for(let i=0;i<100;i++){if((await db.query<{blocked:boolean}>(`SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE $1=ANY(pg_blocking_pids(pid))) AS blocked`,[pid])).rows[0].blocked)return;await new Promise(resolve=>setTimeout(resolve,10));}assert.fail("Expected actual database wait");}
test("bounded-facade fence first blocks a real staff payment until release",async()=>{
  const f=await fixture();await openInvoice(f);const before=await financial(f.lease);let release!:()=>void,ready!:(pid:number)=>void;const gate=new Promise<void>(resolve=>{release=resolve;}),locked=new Promise<number>(resolve=>{ready=resolve;});
  const bounded=withSettlementFencePrototype(f.session.userId,async client=>{await settlementAccess(client,f.session,f.lease,"prepare");},async query=>{await query("LOCK TABLE public.invoices,public.invoice_lines IN SHARE MODE NOWAIT");const pid=(await query<{pid:number}>(`SELECT pg_backend_pid() AS pid`)).rows[0].pid;ready(pid);await gate;});
  let writer:Promise<unknown>|undefined;
  try {const pid=await locked;writer=recordPayment(f.session,{leaseId:f.lease,amountMajor:100,paidOn:f.dates.start,last5:"12345",reference:"Synthetic facade race"});await waitForBlocker(pid);assert.deepEqual(await financial(f.lease),before);release();await bounded;await writer;assert.notDeepEqual(await financial(f.lease),before);}
  finally {release();await Promise.allSettled([bounded,...(writer?[writer]:[])]);}
});
test("real payment writer first makes bounded-facade fence fail NOWAIT",async()=>{
  const f=await fixture(),invoice=await openInvoice(f),before=await financial(f.lease),gate=new Client({connectionString:withDatabase(source,name)});await gate.connect();
  const key=BigInt(`0x${randomBytes(7).toString("hex")}`).toString(),pid=(await gate.query<{pid:number}>(`SELECT pg_backend_pid() AS pid`)).rows[0].pid;await gate.query(`SELECT pg_advisory_lock($1::bigint)`,[key]);
  await db.query(`CREATE FUNCTION app.b011_facade_payment_pause() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.invoice_id='${invoice}'::uuid THEN PERFORM pg_advisory_xact_lock(${key}::bigint); END IF; RETURN NEW; END $$`);await db.query(`CREATE TRIGGER zzz_b011_facade_payment_pause AFTER INSERT ON public.payment_allocations FOR EACH ROW EXECUTE FUNCTION app.b011_facade_payment_pause()`);
  let writer:Promise<unknown>|undefined;
  try {writer=recordPayment(f.session,{leaseId:f.lease,amountMajor:100,paidOn:f.dates.start,last5:"12345",reference:"Synthetic facade race"});await waitForBlocker(pid);
    await assert.rejects(withSettlementFencePrototype(f.session.userId,async client=>{await settlementAccess(client,f.session,f.lease,"prepare");},async query=>{await query("LOCK TABLE public.invoices,public.invoice_lines IN SHARE MODE NOWAIT");}),(error:unknown)=>error instanceof FlowError&&(error.cause as {code?:string})?.code==="55P03");
    assert.deepEqual(await financial(f.lease),before);await gate.query(`SELECT pg_advisory_unlock($1::bigint)`,[key]);await writer;assert.notDeepEqual(await financial(f.lease),before);
  } finally {await gate.query(`SELECT pg_advisory_unlock($1::bigint)`,[key]).catch(()=>{});await Promise.allSettled(writer?[writer]:[]);await db.query(`DROP TRIGGER zzz_b011_facade_payment_pause ON public.payment_allocations`);await db.query(`DROP FUNCTION app.b011_facade_payment_pause()`);await gate.end();}
});

