test("session expiry during deferred flush rolls back diagnostic writes",async()=>{
 const f=await fixture(),request=await diagnosticInput(f),before=await financial(f.lease),key=BigInt(`0x${randomBytes(7).toString("hex")}`).toString();
 await db.query(`CREATE FUNCTION app.b011_test_deferred_wait() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.snapshot->'diagnostic' IS NOT NULL THEN PERFORM pg_advisory_xact_lock(${key}::bigint); PERFORM pg_sleep(1.2); END IF; RETURN NEW; END $$`);await db.query(`CREATE CONSTRAINT TRIGGER b011_test_deferred_wait AFTER INSERT ON app.settlement_versions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION app.b011_test_deferred_wait()`);await db.query(`UPDATE auth_sessions SET expires_at=clock_timestamp()+interval '1 second' WHERE id=$1`,[f.session.sessionId]);
 let pending:ReturnType<typeof saveCandidateDiagnostic>|undefined;
 try {pending=saveCandidateDiagnostic(f.session,name,request);let entered=false;for(let i=0;i<80&&!entered;i++){const attempt=(await db.query<{acquired:boolean}>(`SELECT pg_try_advisory_lock($1::bigint) AS acquired`,[key])).rows[0].acquired;if(attempt){await db.query(`SELECT pg_advisory_unlock($1::bigint)`,[key]);await new Promise(resolve=>setTimeout(resolve,5));}else entered=true;}assert.ok(entered,"deferred trigger entered");assert.equal((await db.query<{live:boolean}>(`SELECT expires_at>clock_timestamp() AS live FROM auth_sessions WHERE id=$1`,[f.session.sessionId])).rows[0].live,true);await assert.rejects(pending,(error:unknown)=>error instanceof FlowError&&error.key==="errors.notFound");assert.equal((await db.query(`SELECT 1 FROM app.settlement_versions WHERE created_by=$1 AND request_id=$2`,[f.session.userId,request.requestId])).rowCount,0);assert.equal((await db.query(`SELECT 1 FROM public.audit_log WHERE event_type='settlement_candidate_diagnostic' AND new_row->>'lease_id'=$1`,[f.lease])).rowCount,0);assert.deepEqual(await financial(f.lease),before);}
 finally {await Promise.allSettled(pending?[pending]:[]);await db.query(`DROP TRIGGER b011_test_deferred_wait ON app.settlement_versions`);await db.query(`DROP FUNCTION app.b011_test_deferred_wait()`);}
});

