test("actual COMMIT acknowledgement loss recovers exact diagnostic request without duplicates",async()=>{
 for(const phase of ["before","after"] as const){const f=await fixture(),request=await diagnosticInput(f),before=await financial(f.lease);
  const fault=await settlementCommitFault(name,phase,()=>saveCandidateDiagnostic(f.session,name,request));assert.equal(fault.tripped,true);assert.equal(fault.commitSeen,true);assert.equal(fault.readySeen,phase==="after");assert.equal(fault.result.status,"rejected");assert.deepEqual(await financial(f.lease),before);
  const existing=await db.query<{id:string}>(`SELECT id FROM app.settlement_versions WHERE created_by=$1 AND request_id=$2`,[f.session.userId,request.requestId]);assert.equal(existing.rowCount,phase==="after"?1:0);
  const recovered=await saveCandidateDiagnostic(f.session,name,request);assert.equal(recovered.recovered,phase==="after");if(phase==="after")assert.equal(recovered.id,existing.rows[0].id);
  assert.equal((await db.query(`SELECT 1 FROM app.settlement_versions WHERE created_by=$1 AND request_id=$2`,[f.session.userId,request.requestId])).rowCount,1);assert.equal((await db.query(`SELECT 1 FROM public.audit_log WHERE event_type='settlement_candidate_diagnostic' AND new_row->>'version_id'=$1`,[recovered.id])).rowCount,1);assert.deepEqual(await financial(f.lease),before);
 }
});

