test("source pin rejects session expiry after actual row pins",async()=>{
 const f=await fixture(),attr=(await db.query<{id:string}>(`SELECT a.id FROM app.settlement_attributions a JOIN app.settlement_allocation_roots r ON r.id=a.root_id WHERE r.lease_id=$1 AND r.category='deposit' LIMIT 1`,[f.lease])).rows[0].id,key=BigInt(`0x${randomBytes(7).toString("hex")}`).toString(),original=(await db.query<{definition:string}>(`SELECT pg_get_functiondef('app.settlement_pin_source_parents(uuid,uuid,text,uuid,uuid,uuid[],uuid[])'::regprocedure) AS definition`)).rows[0].definition,needle="IF v_count<>cardinality(p_attributions) OR NOT EXISTS";
 assert.ok(original.includes(needle));await db.query(original.replace(needle,`PERFORM pg_advisory_xact_lock(${key}::bigint); PERFORM pg_sleep(1.2); ${needle}`));await db.query(`UPDATE auth_sessions SET expires_at=clock_timestamp()+interval '1 second' WHERE id=$1`,[f.session.sessionId]);const client=await gatewayClient(f);await client.query(`SET LOCAL statement_timeout='2s'`);let pending:Promise<unknown>|undefined;
 try {pending=client.query(`SELECT app.settlement_pin_source_parents($1,$1,'live',$2,$3,$4::uuid[],$5::uuid[])`,[ORG_ID,f.lease,f.session.sessionId,[f.evidenceId],[attr]]);let entered=false;for(let i=0;i<80&&!entered;i++){const acquired=(await db.query<{acquired:boolean}>(`SELECT pg_try_advisory_lock($1::bigint) AS acquired`,[key])).rows[0].acquired;if(acquired){await db.query(`SELECT pg_advisory_unlock($1::bigint)`,[key]);await new Promise(resolve=>setTimeout(resolve,5));}else entered=true;}assert.ok(entered,"gateway reached post-pin test barrier");assert.equal((await db.query<{live:boolean}>(`SELECT expires_at>clock_timestamp() AS live FROM auth_sessions WHERE id=$1`,[f.session.sessionId])).rows[0].live,true);await assert.rejects(pending,(error:unknown)=>(error as {code?:string}).code==="42501");}
 finally{await client.query("ROLLBACK").catch(()=>{});await Promise.allSettled(pending?[pending]:[]);await client.end();await db.query(original);}
});

