test("v2 historical recovery works OFF only for exact own unknown request",async()=>{
 const f=await fixture(),requestId=randomUUID(),input={leaseId:f.lease,attributionIds:[],items:[]},old=(await db.query<{id:string}>(`SELECT v.id FROM app.settlement_versions v JOIN app.settlement_records r ON r.id=v.record_id WHERE r.lease_id=$1 ORDER BY v.revision DESC LIMIT 1`,[f.lease])).rows[0].id,preview=await previewV2Unknown(f.session,input);assert.equal(preview.state,"unknown");if(preview.state!=="unknown")throw new Error("Missing source");const expected=preview.fingerprint,version=(await saveV2Unknown(f.session,input,expected,old,requestId)).id;
 await db.query(`UPDATE platform_settings SET value='{"enabled":false,"allowed_org_ids":[]}'::jsonb WHERE key='deposit_settlements'`);assert.deepEqual(await recoverV2UnknownDraft(f.session,input,expected,old,requestId),{id:version,recovered:true,freshness:"unavailable"});assert.deepEqual(await recoverEmptyV2UnknownDraft(f.session,f.lease,old,requestId),{id:version,recovered:true,freshness:"unavailable"});await assert.rejects(recoverEmptyV2UnknownDraft(f.session,f.lease,null,requestId),(error:unknown)=>error instanceof FlowError&&error.key==="errors.generic");assert.equal(await recoverV2UnknownDraft(f.session,input,expected,old,randomUUID()),null);await assert.rejects(recoverV2UnknownDraft(f.session,input,"b".repeat(64),old,requestId),(error:unknown)=>error instanceof FlowError&&error.key==="errors.generic");await assert.rejects(recoverV2UnknownDraft({...f.session,orgId:randomUUID()},input,expected,old,requestId),(error:unknown)=>error instanceof FlowError&&error.key==="errors.notFound");
});

test("v2 staff preview is repeatable UNKNOWN without writes and source change alters digest",async()=>{
 const f=await fixture(),input={leaseId:f.lease,attributionIds:[],items:[]},before=await financial(f.lease),first=await previewV2Unknown(f.session,input),second=await previewV2Unknown(f.session,input);assert.equal(first.state,"unknown");assert.deepEqual(first,second);if(first.state!=="unknown")throw new Error("Missing complete source");assert.equal(first.calculation.authoritative,false);assert.deepEqual(await financial(f.lease),before);
 await db.query(`UPDATE invoices SET status='written_off' WHERE id=$1`,[f.invoice]);const changed=await previewV2Unknown(f.session,input);assert.equal(changed.state,"unknown");if(changed.state!=="unknown")throw new Error("Missing complete source");assert.notEqual(first.fingerprint,changed.fingerprint);
});

