test("v2 loader withholds first-transaction data if staff session is revoked before recheck",async()=>{
 const f=await fixture(),input={leaseId:f.lease,attributionIds:[],items:[]},old=(await db.query<{id:string}>(`SELECT v.id FROM app.settlement_versions v JOIN app.settlement_records r ON r.id=v.record_id WHERE r.lease_id=$1 ORDER BY v.revision DESC LIMIT 1`,[f.lease])).rows[0].id,p=await previewV2Unknown(f.session,input);assert.equal(p.state,"unknown");if(p.state!=="unknown")throw new Error("Missing source");const saved=await saveV2Unknown(f.session,input,p.fingerprint,old,randomUUID()),barrier=new Client({connectionString:withDatabase(source,name)}),writer=new Client({connectionString:withDatabase(source,name)});await barrier.connect();await writer.connect();await barrier.query("BEGIN");await barrier.query("LOCK TABLE public.profiles IN ACCESS EXCLUSIVE MODE");const barrierPid=(await barrier.query<{pid:number}>(`SELECT pg_backend_pid() AS pid`)).rows[0].pid;let loading:ReturnType<typeof loadV2Unknown>|undefined,observed:Promise<{ok:boolean;error?:unknown}>|undefined,revoking:Promise<unknown>|undefined;
 try{loading=loadV2Unknown(f.session,f.lease,saved.id);observed=loading.then(()=>({ok:true}),error=>({ok:false,error}));await waitForBlocker(barrierPid);const loaderPid=(await db.query<{pid:number}>(`SELECT pid FROM pg_stat_activity WHERE $1=ANY(pg_blocking_pids(pid)) AND query LIKE '%settlement_items i LEFT JOIN%'`,[barrierPid])).rows[0]?.pid;assert.ok(loaderPid);await writer.query("BEGIN");revoking=writer.query(`UPDATE auth_sessions SET revoked_at=clock_timestamp() WHERE id=$1`,[f.session.sessionId]);await waitForBlocker(loaderPid);await barrier.query("ROLLBACK");await revoking;const result=await observed;assert.equal(result.ok,false);assert.ok(result.error instanceof FlowError);await writer.query("COMMIT");await assert.rejects(loadV2Unknown(f.session,f.lease,saved.id),(error:unknown)=>error instanceof FlowError&&error.key==="errors.notFound");}
 finally{await barrier.query("ROLLBACK").catch(()=>{});await writer.query("ROLLBACK").catch(()=>{});await Promise.allSettled([...(loading?[loading]:[]),...(revoking?[revoking]:[])]);await barrier.end();await writer.end();}
});
