test("v2 loader withholds data after committed revocation or reset between reads",async()=>{
 for(const change of ["revoke","reset"] as const){const f=await fixture(),input={leaseId:f.lease,attributionIds:[],items:[]},old=(await db.query<{id:string}>(`SELECT v.id FROM app.settlement_versions v JOIN app.settlement_records r ON r.id=v.record_id WHERE r.lease_id=$1 ORDER BY v.revision DESC LIMIT 1`,[f.lease])).rows[0].id,p=await previewV2Unknown(f.session,input);assert.equal(p.state,"unknown");if(p.state!=="unknown")throw new Error("Missing source");const saved=await saveV2Unknown(f.session,input,p.fingerprint,old,randomUUID());
  const run=await settlementSecondConnectionBarrier(name,async()=>{if(change==="revoke")await db.query(`UPDATE auth_sessions SET revoked_at=clock_timestamp() WHERE id=$1`,[f.session.sessionId]);else {await db.query("BEGIN");try{await captureSettlementBeforeDemoReset(db);await db.query("COMMIT");}catch(error){await db.query("ROLLBACK");throw error;}}},()=>loadV2Unknown(f.session,f.lease,saved.id));assert.equal(run.interleaved,true);assert.equal(run.connections,2);assert.equal(run.result.status,"rejected");if(run.result.status==="rejected")assert.ok(run.result.reason instanceof FlowError);
  if(change==="revoke")assert.ok((await db.query(`SELECT 1 FROM auth_sessions WHERE id=$1 AND revoked_at IS NOT NULL`,[f.session.sessionId])).rowCount);else assert.equal((await db.query(`SELECT 1 FROM app.settlement_versions WHERE id=$1`,[saved.id])).rowCount,0);
 }
});

test("v2 empty command concurrent requests and lost acknowledgement recover exactly once",async()=>{
 const f=await fixture(),old=(await db.query<{id:string}>(`SELECT v.id FROM app.settlement_versions v JOIN app.settlement_records r ON r.id=v.record_id WHERE r.lease_id=$1 ORDER BY v.revision DESC LIMIT 1`,[f.lease])).rows[0].id,request=randomUUID(),before=await financial(f.lease),results=await Promise.all([createV2EmptyCommand(f.session,f.lease,old,request),createV2EmptyCommand(f.session,f.lease,old,request)]);assert.ok(results.some(result=>result.ok));const retries=await Promise.all([createV2EmptyCommand(f.session,f.lease,old,request),createV2EmptyCommand(f.session,f.lease,old,request)]);assert.ok(retries[0].ok&&retries[1].ok);if(!retries[0].ok||!retries[1].ok)throw new Error("Missing recovered result");assert.equal(retries[0].id,retries[1].id);assert.equal((await db.query(`SELECT 1 FROM app.settlement_versions WHERE created_by=$1 AND request_id=$2`,[f.session.userId,request])).rowCount,1);assert.equal((await db.query(`SELECT 1 FROM public.audit_log WHERE event_type='settlement_version_saved' AND new_row->>'version_id'=$1`,[retries[0].id])).rowCount,1);assert.deepEqual(await financial(f.lease),before);
 const g=await fixture(),previous=(await db.query<{id:string}>(`SELECT v.id FROM app.settlement_versions v JOIN app.settlement_records r ON r.id=v.record_id WHERE r.lease_id=$1 ORDER BY v.revision DESC LIMIT 1`,[g.lease])).rows[0].id,key=randomUUID(),finance=await financial(g.lease),fault=await settlementCommitFault(name,"after",()=>createV2EmptyCommand(g.session,g.lease,previous,key),async()=>{await db.query(`UPDATE platform_settings SET value='{"enabled":false,"allowed_org_ids":[]}'::jsonb WHERE key='deposit_settlements'`);},3);assert.equal(fault.tripped,true);assert.equal(fault.commitCount,3);assert.equal(fault.readySeen,true);assert.equal(fault.result.status,"fulfilled");if(fault.result.status!=="fulfilled")throw new Error("Missing command result");assert.equal(fault.result.value.ok,true);if(!fault.result.value.ok)throw new Error("Missing recovered ID");assert.equal((await db.query(`SELECT 1 FROM app.settlement_versions WHERE created_by=$1 AND request_id=$2`,[g.session.userId,key])).rowCount,1);assert.equal((await db.query(`SELECT 1 FROM public.audit_log WHERE event_type='settlement_version_saved' AND new_row->>'version_id'=$1`,[fault.result.value.id])).rowCount,1);assert.deepEqual(await financial(g.lease),finance);
});

test("statement terminal closes once, blocks direct insert and preserves legacy replay",async()=>{
 const f=await fixture(),legacy=(await db.query<{id:string;request_id:string;source_fingerprint:string;snapshot:{input:Parameters<typeof previewSettlement>[1];requestExpectedVersion:string|null}}>(`SELECT id,request_id,source_fingerprint,snapshot FROM app.settlement_versions WHERE lease_id=$1 ORDER BY revision LIMIT 1`,[f.lease])).rows[0];
 const terminal=(request:string,close:boolean)=>svc(f.session.userId,async client=>{await settlementV2HistoricalContext(client,f.session,f.lease);return statementTerminalOn(client,f.session,f.lease,request,close);});
 await assert.rejects(svc(f.session.userId,async client=>{await settlementV2HistoricalContext(client,f.session,f.lease);try{await statementTerminalOn(client,f.session,f.lease,legacy.request_id,true);}catch(error){assert.equal((error as {code?:string}).code,"23514");assert.equal((error as Error).message,"Statement terminal conflict");throw error;}}),(error:unknown)=>error instanceof FlowError&&(error.cause as {code?:string})?.code==="23514");
 const replay=await saveSettlement(f.session,legacy.snapshot.input,legacy.source_fingerprint,legacy.snapshot.requestExpectedVersion,legacy.request_id,false);assert.equal(replay.id,legacy.id);
 const key=randomUUID();assert.deepEqual(await terminal(key,false),{state:"unresolved"});assert.deepEqual(await terminal(key,true),{state:"closed"});assert.deepEqual(await terminal(key,true),{state:"closed"});
 const before=(await db.query<{n:string}>(`SELECT count(*)::text n FROM public.audit_log WHERE org_id=$1 AND event_type='settlement_statement_closed' AND new_row->>'request_id'=$2`,[ORG_ID,key])).rows[0].n;assert.equal(before,"1");
 await assert.rejects(svc(f.session.userId,async client=>{await client.query(`INSERT INTO public.audit_log(org_id,actor_user_id,actor_role,table_name,row_id,action,event_type,new_row,reason) VALUES($1,$2,'app','auth_events','synthetic','insert','synthetic_rollback','{}','synthetic')`,[ORG_ID,f.session.userId]);try{await client.query(`INSERT INTO app.settlement_versions(org_id,lease_id,record_id,revision,published,snapshot,source_fingerprint,created_by,request_id) SELECT org_id,lease_id,record_id,999,false,snapshot,source_fingerprint,created_by,$2 FROM app.settlement_versions WHERE id=$1`,[legacy.id,key]);}catch(error){assert.equal((error as {code?:string}).code,"23514");assert.equal((error as Error).message,"Statement request closed");throw error;}}),(error:unknown)=>error instanceof FlowError&&(error.cause as {code?:string})?.code==="23514");
 assert.equal((await db.query<{n:string}>(`SELECT count(*)::text n FROM public.audit_log WHERE org_id=$1 AND event_type='synthetic_rollback'`,[ORG_ID])).rows[0].n,"0");
 assert.equal((await db.query<{n:string}>(`SELECT count(*)::text n FROM app.settlement_versions WHERE created_by=$1 AND request_id=$2`,[f.session.userId,key])).rows[0].n,"0");
 await assert.rejects(svc(f.session.userId,async client=>client.query(`DELETE FROM app.settlement_statement_closures WHERE actor_id=$1 AND request_id=$2`,[f.session.userId,key])));
});
