 const insert=(c:Client,key:string)=>c.query(`INSERT INTO app.settlement_versions(org_id,lease_id,record_id,revision,published,snapshot,source_fingerprint,created_by,request_id) SELECT org_id,lease_id,record_id,999,false,snapshot,source_fingerprint,created_by,$2 FROM app.settlement_versions WHERE id=$1`,[legacy,key]);
