test("terminal expiry during deferred flush rolls back closure and audit",async()=>{
 const f=await fixture(),request=randomUUID(),key=BigInt(`0x${randomBytes(7).toString("hex")}`).toString(),before=await financial(f.lease);await db.query(`CREATE FUNCTION app.b011_test_terminal_expiry() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM pg_advisory_xact_lock(${key}::bigint); PERFORM pg_sleep(1.2); RETURN NEW; END $$`);await db.query(`REVOKE ALL ON FUNCTION app.b011_test_terminal_expiry() FROM PUBLIC,anon,authenticated,service_role`);await db.query(`CREATE CONSTRAINT TRIGGER b011_test_terminal_expiry AFTER INSERT ON app.settlement_statement_closures DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION app.b011_test_terminal_expiry()`);await db.query(`UPDATE public.auth_sessions SET expires_at=clock_timestamp()+interval '1 second' WHERE id=$1`,[f.session.sessionId]);const pending=resolveStatementTerminal(f.session,f.lease,request,true);const observed=pending.then(()=>null,error=>error);
 try {let entered=false;for(let i=0;i<80&&!entered;i++){const acquired=(await db.query<{acquired:boolean}>(`SELECT pg_try_advisory_lock($1::bigint) acquired`,[key])).rows[0].acquired;if(acquired){await db.query(`SELECT pg_advisory_unlock($1::bigint)`,[key]);await new Promise(resolve=>setTimeout(resolve,5));}else entered=true;}assert.ok(entered);assert.equal((await db.query<{live:boolean}>(`SELECT expires_at>clock_timestamp() live FROM public.auth_sessions WHERE id=$1`,[f.session.sessionId])).rows[0].live,true);const error=await observed;assert.ok(error instanceof FlowError);assert.equal(error.key,"errors.notFound");assert.equal((await db.query(`SELECT 1 FROM app.settlement_statement_closures WHERE actor_id=$1 AND request_id=$2`,[f.session.userId,request])).rowCount,0);assert.equal((await db.query(`SELECT 1 FROM public.audit_log WHERE event_type='settlement_statement_closed' AND new_row->>'request_id'=$1`,[request])).rowCount,0);assert.deepEqual(await financial(f.lease),before);}finally{await observed;await db.query(`DROP TRIGGER b011_test_terminal_expiry ON app.settlement_statement_closures`);await db.query(`DROP FUNCTION app.b011_test_terminal_expiry()`);}
});
